#include <bits/stdc++.h>
using namespace std;

bool isLucky(long long x){
    if(x<=0) return false;
    while(x>0){
        int d=x%10;
        if(d!=4&&d!=7) return false;
        x/=10;
    }
    return true;
}

int main(){
    long long n,k;
    if(!(cin>>n>>k)) return 0;
    // factorials
    vector<long long> fact(21);
    fact[0]=1;
    for(int i=1;i<=20;i++) fact[i]=fact[i-1]*i;
    if(n<=20 && fact[n]<k){ cout<<-1<<endl; return 0; }
    int m=0;
    while(m<20 && m<n && fact[m]<k) m++;
    // m elements permuted at the end
    long long fixedCount = n-m;
    // count lucky numbers <= fixedCount
    long long cnt=0;
    // generate lucky numbers
    vector<long long> lucky;
    for(int len=1;len<=10;len++){
        for(int mask=0;mask<(1<<len);mask++){
            long long v=0;
            for(int i=len-1;i>=0;i--){
                v=v*10+(((mask>>i)&1)?7:4);
            }
            lucky.push_back(v);
        }
    }
    for(size_t i=0;i<lucky.size();i++) if(lucky[i]<=fixedCount) cnt++;
    // build k-th permutation of values fixedCount+1 .. n
    vector<long long> vals;
    for(long long v=fixedCount+1;v<=n;v++) vals.push_back(v);
    long long kk=k-1;
    vector<long long> perm;
    int sz=vals.size();
    for(int i=0;i<sz;i++){
        long long f=fact[sz-i-1];
        long long idx=kk/f;
        kk%=f;
        perm.push_back(vals[idx]);
        vals.erase(vals.begin()+idx);
    }
    for(int i=0;i<sz;i++){
        long long pos=fixedCount+1+i;
        if(isLucky(pos)&&isLucky(perm[i])) cnt++;
    }
    cout<<cnt<<endl;
    return 0;
}
